import jsonschema

class MetaSchemaRegistry:
    def __init__(self):
        # Initialize an empty dictionary to store meta-schemas and vocabularies
        self.registry = {}

    def register_schema(self, name, schema):
        # Register a new meta-schema or vocabulary with its name and schema
        if name in self.registry:
            print(f"Error: Schema '{name}' already exists.")
        else:
            self.registry[name] = schema
            print(f"Schema '{name}' registered successfully.")

    def get_schema(self, name):
        # Retrieve a previously registered meta-schema or vocabulary by name
        return self.registry.get(name, None)

    def list_schemas(self):
        # List all registered meta-schemas or vocabularies
        if not self.registry:
            print("No schemas found.")
        else:
            for name, schema in self.registry.items():
                print(f"Name: {name}, Schema: {schema}")

# Example usage
registry = MetaSchemaRegistry()
registry.register_schema('person', {
    "type": "object",
    "properties": {
        "name": {"type": "string"},
        "age": {"type": "integer"}
    },
    "required": ["name", "age"]
})

registry.register_schema('address', {
    "type": "object",
    "properties": {
        "street": {"type": "string"},
        "city": {"type": "string"},
        "zip": {"type": "string"}
    },
    "required": ["street", "city", "zip"]
})

registry.list_schemas()

# Retrieving a schema
person_schema = registry.get_schema('person')
print(person_schema)
```

This Python code defines a `MetaSchemaRegistry` class that allows registering and retrieving meta-schemas and vocabularies using JSON Schema. The `register_schema` method adds a new schema to the registry, ensuring uniqueness by checking if the name already exists. The `get_schema` method retrieves a schema by name, returning `None` if the schema does not exist. The `list_schemas` method lists all registered schemas. An example usage demonstrates registering two schemas, listing them, and retrieving one.

