import datetime

def parse_time_expression(time_str):
    # Custom function to parse time expressions
    try:
        # Attempt to parse the time string using the datetime.strptime method
        return datetime.datetime.strptime(time_str, "%Y-%m-%d %H:%M:%S")
    except ValueError:
        # Handle the case where parsing fails by returning None
        print("Invalid time format")
        return None

# Example usage of the parse_time_expression function
time_input = "2023-10-05 14:30:00"
parsed_time = parse_time_expression(time_input)
if parsed_time:
    print(f"Parsed time: {parsed_time}")
else:
    print("Failed to parse time")
```

