# Import necessary libraries
from flask import Flask, render_template, request, redirect, url_for
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required
from datetime import datetime

# Initialize Flask app
app = Flask(__name__)
app.config['SECRET_KEY'] = 'your_secret_key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///project_management.db'
db = SQLAlchemy(app)
login_manager = LoginManager()
login_manager.init_app(app)

# Define User model
class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password = db.Column(db.String(120), nullable=False)
    projects = db.relationship('Project', backref='manager', lazy=True)

# Define Project model
class Project(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(120), nullable=False)
    start_date = db.Column(db.DateTime, default=datetime.utcnow)
    end_date = db.Column(db.DateTime, nullable=True)
    manager_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    tasks = db.relationship('Task', backref='project', lazy=True)

# Define Task model
class Task(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(120), nullable=False)
    description = db.Column(db.Text, nullable=True)
    status = db.Column(db.String(50), nullable=False)
    due_date = db.Column(db.DateTime, nullable=True)
    project_id = db.Column(db.Integer, db.ForeignKey('project.id'), nullable=False)

# Create database tables
with app.app_context():
    db.create_all()

# Login route
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = User.query.filter_by(username=username).first()
        if user and user.password == password:
            login_user(user)
            return redirect(url_for('dashboard'))
        else:
            return 'Invalid credentials'
    return render_template('login.html')

# Logout route
@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('login'))

# Dashboard route
@app.route('/')
@login_required
def dashboard():
    projects = Project.query.filter_by(manager_id=current_user.id).all()
    return render_template('dashboard.html', projects=projects)

# Add project route
@app.route('/add_project', methods=['GET', 'POST'])
@login_required
def add_project():
    if request.method == 'POST':
        name = request.form['name']
        start_date = request.form['start_date']
        end_date = request.form['end_date']
        new_project = Project(name=name, start_date=start_date, end_date=end_date, manager_id=current_user.id)
        db.session.add(new_project)
        db.session.commit()
        return redirect(url_for('dashboard'))
    return render_template('add_project.html')

# Run the application
if __name__ == '__main__':
    app.run(debug=True)
```

This Python code sets up a basic project management system using Flask and SQLAlchemy. It includes models for users, projects, and tasks, as well as routes for login, logout, and managing projects. The system supports task tracking, team collaboration, and progress reporting, making it suitable for various types of projects.

```python
import json

# Define the JSONPath grammar rules
JSONPATH_GRAMMAR = """
    expression: element | path_expression | array_expression
    element: identifier | number
    path_expression: path_elements [index]
    array_expression: array_elements [index]
    path_elements: path_element*
    path_element: identifier | index
    index: '[' number ']'
    number: digit+
    identifier: letter+ digit*
    digit: 0-9
    letter: A-Z | a-z
"""

# Tokenize the JSONPath expression
def tokenize(expression):
    tokens = []
    current_token = ""
    in_number = False
    in_string = False
    for char in expression:
        if char == '"':
            if in_string:
                tokens.append((current_token, "STRING"))
                current_token = ""
                in_string = False
            else:
                in_string = True
        elif char.isdigit():
            if in_number:
                current_token += char
            else:
                current_token = char
                in_number = True
        elif char.isalpha():
            if in_number:
                tokens.append((current_token, "NUMBER"))
                current_token = ""
                in_number = False
            else:
                current_token += char
        elif char == "[":
            tokens.append((current_token, "BRACKET_OPEN"))
            current_token = ""
        elif char == "]":
            tokens.append((current_token, "BRACKET_CLOSE"))
            current_token = ""
        elif char == "." or char == ":":
            if in_string:
                tokens.append((current_token, "STRING"))
                current_token = ""
                in_string = False
            else:
                tokens.append((current_token, "OPERATOR"))
                current_token = ""
        else:
            raise ValueError(f"Invalid character: {char}")
    if in_number:
        tokens.append((current_token, "NUMBER"))
    elif in_string:
        tokens.append((current_token, "STRING"))
    return tokens

# Parse the JSONPath expression into an AST
class Node:
    def __init__(self, type, value=None, children=None):
        self.type = type
        self.value = value
        self.children = children if children else []

def parse(tokens):
    ast = {}
    current_node = None
    current_type = None
    current_value = None
    stack = []

    for token in tokens:
        token_type, token_value = token

        if token_type == "STRING":
            if current_type == "NUMBER":
                raise ValueError("Cannot mix NUMBER and STRING")
            current_value = float(token_value)
            current_type = "NUMBER"
        elif token_type == "NUMBER":
            if current_type == "STRING":
                raise ValueError("Cannot mix NUMBER and STRING")
            current_value = int(token_value)
            current_type = "NUMBER"
        elif token_type == "OPERATOR":
            if not current_node or current_node.type != "OPERATOR":
                raise ValueError("Expected operator before next operator")
            current_node.children.append(Node(current_type, current_value))
            current_node = None
            current_type = None
            current_value = None
            if current_node:
                current_node.children.append(Node(current_type, current_value))
            current_node = Node(token_type, token_value)
        elif token_type == "BRACKET_OPEN":
            stack.append(current_node)
            current_node = Node("BRACKET_OPEN", None)
        elif token_type == "BRACKET_CLOSE":
            parent_node = stack.pop()
            current_node.children.append(parent_node)

    if current_node:
        ast["root"] = current_node

    return ast

# Evaluate the AST using the standard JSONPath functions
def evaluate(ast, data):
    def get_item(path, obj):
        parts = path.split('.')
        current_obj = obj
        for part in parts:
            try:
                current_obj = current_obj[part]
            except KeyError:
                return None
        return current_obj

    def apply_operator(op, left, right):
        if op == "+":
            return left + right
        elif op == "-":
            return left - right
        elif op == "*":
            return left * right
        elif op == "/":
            return left / right
        elif op == "==":
            return left == right
        elif op == "!=":
            return left != right
        elif op == ">":
            return left > right
        elif op == "<":
            return left < right
        elif op == ">=":
            return left >= right
        elif op == "<=":
            return left <= right
        else:
            raise ValueError(f"Unsupported operator: {op}")

    def eval_expr(expr):
        if expr.type == "IDENTIFIER":
            return get_item(expr.value, data)
        elif expr.type == "NUMBER":
            return expr.value
        elif expr.type == "OPERATOR":
            right = eval_expr(expr.children[1])
            left = eval_expr

