import requests
import json

class ONTAPAPI:
    def __init__(self, base_url, api_key):
        self.base_url = base_url
        self.api_key = api_key
        self.headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {api_key}'
        }

    def create_volume(self, volume_name, size_gb, snapshot_policy):
        url = f'{self.base_url}/storage/volumes'
        payload = {
            "name": volume_name,
            "size": size_gb * 1024**3,  # convert GB to bytes
            "snapshotPolicyName": snapshot_policy
        }
        response = requests.post(url, headers=self.headers, data=json.dumps(payload))
        return response.json()

    def create_snapshot(self, volume_name, snapshot_name):
        url = f'{self.base_url}/storage/snapshots'
        payload = {
            "volumeName": volume_name,
            "name": snapshot_name
        }
        response = requests.post(url, headers=self.headers, data=json.dumps(payload))
        return response.json()

    def get_storage_efficiency(self):
        url = f'{self.base_url}/storage/efficiencies'
        response = requests.get(url, headers=self.headers)
        return response.json()

# Example usage
ontap_api = ONTAPAPI('https://your-ontap-api-url', 'your-api-key')
volume_response = ontap_api.create_volume('new-volume', 500, 'default')
snapshot_response = ontap_api.create_snapshot('existing-volume', 'new-snapshot')
storage_efficiency = ontap_api.get_storage_efficiency()
```

