```python
import pyparsing as pp

# Define the grammar for C-family source files
def c_program():
    """Parse a C-family program."""
    return (
        pp.Forward()  # Start with a forward declaration for the main function
        + pp.ZeroOrMore(pp.CaselessLiteral("main") + "(") +
        pp.Optional(pp.Word(pp.alphas)) + pp.Literal(")") +
        pp.ZeroOrMore(c_statement()) + pp.Literal(";")
    )

def c_statement():
    """Parse a C statement."""
    return (
        c_assignment() | c_expression()
    )

def c_assignment():
    """Parse a C assignment statement."""
    return (
        pp.Word(pp.alphas) + "=" +
        c_expression()
    )

def c_expression():
    """Parse a C expression."""
    return (
        c_primary_expr() + (
            pp.Optional(pp.Literal("+")) |
            pp.Optional(pp.Literal("-")) |
            pp.Optional(pp.Literal("*")) |
            pp.Optional(pp.Literal("/"))
        ) +
        c_expression()
    )

def c_primary_expr():
    """Parse a C primary expression."""
    return (
        pp.Word(pp.alphas) |
        pp.Literal("(") + c_expression() + pp.Literal(")")
    )

# Parse a C source file
source_code = """
#include <stdio.h>

int main(int argc, char *argv[]) {
    int x = 5;
    printf("%d\n", x);
    return 0;
}
"""

parsed_program = c_program().parseString(source_code)

# Function to convert AST nodes to XML format
def ast_to_xml(node):
    if isinstance(node, pp.ParseResults):
        xml_node = "<node>"
        for key in node:
            xml_node += f"<{key}>{ast_to_xml(node[key])}</{key}>"
        xml_node += "</node>"
        return xml_node
    elif isinstance(node, str):
        return f'<string>{node}</string>'
    else:
        return str(node)

# Generate XML representation of the parsed program
xml_representation = ast_to_xml(parsed_program)
print(xml_representation)
```

This Python code snippet defines a parser for C-family source files using the `pyparsing` library. It parses simple statements like assignments and expressions into an abstract syntax tree (AST), which is then converted to an XML representation. The `ast_to_xml` function recursively converts each node in the AST into an XML element, including strings and basic arithmetic operations. This allows for easy visualization and analysis of the structure of C programs.

