# Set up the base URL for Cloudflare API
BASE_URL = 'https://api.cloudflare.com/client/v4'

def get_account_info():
    # Construct the request URL for retrieving account information
    url = f"{BASE_URL}/accounts/me"
    headers = {
        "Authorization": f"Bearer {CLOUDFLARE_API_KEY}",
        "Content-Type": "application/json"
    }

    response = requests.get(url, headers=headers)

    if response.status_code == 200:
        return response.json()
    else:
        print(f"Failed to retrieve account info. Status code: {response.status_code}")
        return None

def create_dns_record(zone_id, record_name, record_type, content):
    # Construct the request URL for creating a new DNS record
    url = f"{BASE_URL}/zones/{zone_id}/dns_records"
    headers = {
        "Authorization": f"Bearer {CLOUDFLARE_API_KEY}",
        "Content-Type": "application/json"
    }
    data = {
        "type": record_type,
        "name": record_name,
        "content": content,
        "ttl": 120
    }

    response = requests.post(url, headers=headers, json=data)

    if response.status_code == 201:
        return response.json()
    else:
        print(f"Failed to create DNS record. Status code: {response.status_code}")
        return None

