import os
import subprocess

class DataManagementSystem:
    def __init__(self, project_name):
        self.project_name = project_name
        self.repo_path = f"{project_name}/data"

    def initialize_repo(self):
        if not os.path.exists(self.repo_path):
            os.makedirs(self.repo_path)
            subprocess.run(["git", "init"], cwd=self.repo_path)

    def add_files(self, files):
        for file in files:
            subprocess.run(["git", "add", file], cwd=self.repo_path)

    def commit_changes(self, message):
        subprocess.run(["git", "commit", "-m", message], cwd=self.repo_path)

    def push_to_remote(self, remote_name="origin"):
        subprocess.run(["git", "push", remote_name], cwd=self.repo_path)

    def pull_from_remote(self, remote_name="origin"):
        subprocess.run(["git", "pull", remote_name], cwd=self.repo_path)

    def create_branch(self, branch_name):
        subprocess.run(["git", "checkout", "-b", branch_name], cwd=self.repo_path)

    def switch_branch(self, branch_name):
        subprocess.run(["git", "checkout", branch_name], cwd=self.repo_path)

    def merge_branches(self, source_branch, target_branch):
        subprocess.run(["git", "merge", source_branch], cwd=self.repo_path)

# Example usage
dm_system = DataManagementSystem("my_project")
dm_system.initialize_repo()
dm_system.add_files(["data.csv", "metadata.json"])
dm_system.commit_changes("Initial commit of data files")
dm_system.create_branch("feature-branch")
dm_system.switch_branch("feature-branch")
dm_system.add_files(["new-feature.txt"])
dm_system.commit_changes("Added new feature")
dm_system.merge_branches("feature-branch", "main")
dm_system.push_to_remote()
```

This Python class `DataManagementSystem` encapsulates the basic functionalities of managing a data repository using Git. It includes methods for initializing a new Git repository, adding files, committing changes, pushing to a remote repository, pulling from a remote repository, creating branches, switching branches, merging branches, and more. The example usage demonstrates how to use this class to manage a data project.

