import dbfread
from sqlalchemy import create_engine
from sqlalchemy.exc import SQLAlchemyError

# Function to extract table names and columns from a DBF file
def extract_dbf_info(file_path):
    try:
        engine = create_engine(f"dbf://{file_path}")
        connection = engine.connect()
        tables = connection.execute("DESCRIBE").fetchall()

        table_names = [table[0] for table in tables]
        column_info = {table[0]: [] for table in tables}

        for table_name, columns in tables:
            for column in columns:
                column_info[table_name].append((column[0], column[1]))

        return table_names, column_info
    except SQLAlchemyError as e:
        print(f"Error extracting DBF info: {e}")
        return None, None

# Example usage
file_path = "path_to_your_dbf_file.dbf"
table_names, column_info = extract_dbf_info(file_path)
if table_names and column_info:
    print("Table Names:", table_names)
    print("Column Info:")
    for table, cols in column_info.items():
        print(f"{table}: {cols}")

