import functools

def retry(max_attempts, callback):
    @functools.wraps(callback)
    def wrapper(*args, **kwargs):
        attempt = 0
        while attempt < max_attempts:
            try:
                return callback(*args, **kwargs)
            except Exception as e:
                print(f"Attempt {attempt + 1} failed: {e}")
                attempt += 1
        callback(*args, **kwargs)  # Call the callback after all attempts fail
    return wrapper
```

**Explanation**:
- The `retry` function is defined to take two parameters: `max_attempts`, which specifies the maximum number of times the wrapped function should be retried, and `callback`, which is the function that will be called if all attempts fail.
- Inside the `wrapper` function, a loop is used to attempt calling the `callback` function up to the specified `max_attempts`.
- For each attempt, the `callback` is executed. If an exception occurs (which is caught by the `except` block), the current attempt count (`attempt`) is printed, and the loop continues to the next attempt.
- After the loop finishes without the `callback` being called successfully (i.e., after all attempts have been exhausted), the `callback` is called again with the same arguments. This ensures that even if the initial call fails, the user can still get an opportunity to handle the failure using the provided callback function.

import docker_compose
from pycomposefile.parser import parse
from pycomposefile.exceptions import ComposeFileException

def load_docker_compose(file_path):
    with open(file_path, 'r') as file:
        compose_content = file.read()
    return parse(compose_content)

def extract_services(parsed_data):
    return parsed_data.get('services', {})

def extract_networks(parsed_data):
    return parsed_data.get('networks', {})

def extract_volumes(parsed_data):
    return parsed_data.get('volumes', {})

def main():
    try:
        file_path = 'docker-compose.yml'
        parsed_data = load_docker_compose(file_path)

        services = extract_services(parsed_data)
        for service_name, service_info in services.items():
            print(f"Service: {service_name}")
            for key, value in service_info.items():
                print(f"  {key}: {value}")

        networks = extract_networks(parsed_data)
        for network_name, network_info in networks.items():
            print(f"Network: {network_name}")
            for key, value in network_info.items():
                print(f"  {key}: {value}")

        volumes = extract_volumes(parsed_data)
        for volume_name, volume_info in volumes.items():
            print(f"Volume: {volume_name}")
            for key, value in volume_info.items():
                print(f"  {key}: {value}")
    except ComposeFileException as e:
        print(f"Error parsing Docker Compose file: {e}")

if __name__ == "__main__":
    main()

