import requests

# Define the base URL for the Smartling API
base_url = "https://api.smartling.com/v2"

# Set your Smartling API credentials
api_key = "your_api_key"
api_secret = "your_api_secret"

# Create a session to handle HTTP requests
session = requests.Session()

# Function to authenticate with the Smartling API
def authenticate():
    url = f"{base_url}/auth/token"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Basic {api_key}:{api_secret}"
    }
    response = session.post(url, json={"type": "basic"})
    if response.status_code == 200:
        return response.json()["access_token"]
    else:
        raise Exception("Failed to authenticate with Smartling API")

# Authenticate and get an access token
access_token = authenticate()

# Function to create a new translation project
def create_project(project_name):
    url = f"{base_url}/projects"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }
    data = {
        "name": project_name,
        "language": "en",  # Replace with desired language
        "source_language": "en",  # Replace with source language
        "target_languages": ["fr", "de"]  # Add target languages as needed
    }
    response = session.post(url, headers=headers, json=data)
    if response.status_code == 201:
        return response.json()
    else:
        raise Exception("Failed to create project")

# Function to retrieve all projects
def get_projects():
    url = f"{base_url}/projects"
    headers = {
        "Authorization": f"Bearer {access_token}"
    }
    response = session.get(url, headers=headers)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception("Failed to retrieve projects")

# Function to update an existing project
def update_project(project_id, updated_data):
    url = f"{base_url}/projects/{project_id}"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {access_token}"
    }
    response = session.put(url, headers=headers, json=updated_data)
    if response.status_code == 200:
        return response.json()
    else:
        raise Exception("Failed to update project")

# Function to delete a project
def delete_project(project_id):
    url = f"{base_url}/projects/{project_id}"
    headers = {
        "Authorization": f"Bearer {access_token}"
    }
    response = session.delete(url, headers=headers)
    if response.status_code == 204:
        return True
    else:
        raise Exception("Failed to delete project")

# Example usage
