import numpy as np
from scipy.spatial import distance

# Define a class for fuzzy sets
class FuzzySet:
    def __init__(self, membership_function):
        # Initialize the membership function
        self.membership_function = membership_function

    @property
    def domain(self):
        return self.membership_function.domain

    @domain.setter
    def domain(self, new_domain):
        self.membership_function.domain = new_domain

    def evaluate(self, value):
        # Evaluate the membership degree at a given value
        if value in self.domain:
            return self.membership_function(value)
        else:
            raise ValueError("Value not within domain")

    def __add__(self, other):
        # Perform fuzzy addition with another fuzzy set
        if isinstance(other, FuzzySet):
            if self.domain != other.domain:
                raise ValueError("Domains must be equal")
            result = FuzzySet(lambda x: max(self.evaluate(x), other.evaluate(x)))
            return result
        else:
            raise TypeError("Can only add FuzzySet instances")

    def __sub__(self, other):
        # Perform fuzzy subtraction with another fuzzy set
        if isinstance(other, FuzzySet):
            if self.domain != other.domain:
                raise ValueError("Domains must be equal")
            result = FuzzySet(lambda x: min(self.evaluate(x), other.evaluate(x)))
            return result
        else:
            raise TypeError("Can only subtract FuzzySet instances")

    def __mul__(self, other):
        # Perform fuzzy multiplication with another fuzzy set
        if isinstance(other, FuzzySet):
            if self.domain != other.domain:
                raise ValueError("Domains must be equal")
            result = FuzzySet(lambda x: self.evaluate(x) * other.evaluate(x))
            return result
        else:
            raise TypeError("Can only multiply FuzzySet instances")

    def __truediv__(self, other):
        # Perform fuzzy division with another fuzzy set
        if isinstance(other, FuzzySet):
            if self.domain != other.domain:
                raise ValueError("Domains must be equal")
            if other.evaluate(0) == 0:
                raise ZeroDivisionError("Cannot divide by zero")
            result = FuzzySet(lambda x: self.evaluate(x) / other.evaluate(x))
            return result
        else:
            raise TypeError("Can only divide FuzzySet instances")

    def __eq__(self, other):
        # Check if two fuzzy sets are equal
        if isinstance(other, FuzzySet):
            if self.domain != other.domain:
                return False
            return all(np.isclose(self.evaluate(x), other.evaluate(x)) for x in self.domain)
        else:
            return False

    def __repr__(self):
        # Return a string representation of the fuzzy set
        return f"FuzzySet({self.membership_function})"

# Define a simple Gaussian membership function
def gaussian_membership(x, mu, sigma):
    return np.exp(-((x - mu) ** 2) / (2 * sigma ** 2))

# Example usage
mu1, sigma1 = 5, 2
mu2, sigma2 = 10, 3
fset1 = FuzzySet(gaussian_membership)
fset2 = FuzzySet(gaussian_membership)

result = fset1 + fset2
print(result)
```

This code snippet defines a `FuzzySet` class that can represent fuzzy sets using any membership function provided. The class supports basic arithmetic operations such as addition, subtraction, multiplication, and division, which are performed element-wise across the domain of the fuzzy sets. Additionally, it includes an equality check and a string representation method. The example demonstrates how to create and use a Gaussian membership function to create fuzzy sets and perform operations on them.

