from packaging.version import Version

# Function to parse a version string and return a Version object
def parse_version(version_string):
    try:
        return Version(version_string)
    except ValueError as e:
        print(f"Invalid version: {version_string}. Error: {e}")
        return None

# Function to upgrade a given version by one patch level
def upgrade_version(version):
    if version:
        upgraded_version = version.bump_patch()
        print(f"Upgraded version: {upgraded_version}")
    else:
        print("No valid version provided.")

# Example usage
original_version = "1.2.3"
parsed_version = parse_version(original_version)
if parsed_version:
    upgrade_version(parsed_version)
```

