import ray

# Initialize Ray cluster
ray.init(address="auto")

# Define a class to represent a dataset in the catalog
class Dataset:
    def __init__(self, name, schema):
        self.name = name
        self.schema = schema

# Define a class to represent a catalog
class DataCatalog:
    def __init__(self):
        # Use a dictionary to store datasets
        self.datasets = {}

    @ray.remote(num_cpus=1)
    def create_dataset(self, name, schema):
        # Create a new dataset and add it to the catalog
        dataset = Dataset(name, schema)
        self.datasets[name] = dataset
        return dataset

    @ray.remote(num_cpus=1)
    def delete_dataset(self, name):
        # Remove a dataset from the catalog if it exists
        if name in self.datasets:
            del self.datasets[name]

    @ray.remote(num_cpus=1)
    def get_dataset(self, name):
        # Get a dataset from the catalog by name
        return self.datasets.get(name)

# Example usage of the DataCatalog
if __name__ == "__main__":
    catalog = DataCatalog()

    # Create a new dataset
    dataset_name = "example_dataset"
    dataset_schema = {"id": "int", "name": "str"}
    created_dataset = catalog.create_dataset.remote(dataset_name, dataset_schema)
    dataset_id = ray.get(created_dataset)

    # Delete the dataset
    deleted_dataset = catalog.delete_dataset.remote(dataset_name)
    ray.get(deleted_dataset)

    # Get the dataset again
    retrieved_dataset = catalog.get_dataset.remote(dataset_name)
    print(ray.get(retrieved_dataset))
```

