import Foundation

# Define the notification center class
class NotificationCenter:
    def __init__(self):
        self.notifications = {}

    # Function to register a notification
    def register_notification(self, name, callback):
        self.notifications[name] = callback

    # Function to send a notification with a payload
    def send_notification(self, name, payload=None):
        if name in self.notifications:
            self.notifications[name](payload)

# Wrapper function for sending notifications
def notify(title, body, sound=None):
    nc = NotificationCenter()

    def handler(payload):
        print(f"Notification received: Title={title}, Body={body}")
        if sound:
            print(f"Playing sound: {sound}")

    nc.register_notification("default", handler)
    nc.send_notification("default", {"title": title, "body": body, "sound": sound})

# Example usage
notify("Hello", "This is a test notification")
```

