```python
class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, current_node, value):
        if value < current_node.value:
            if not current_node.left:
                current_node.left = TreeNode(value)
            else:
                self._insert_recursive(current_node.left, value)
        elif value > current_node.value:
            if not current_node.right:
                current_node.right = TreeNode(value)
            else:
                self._insert_recursive(current_node.right, value)
        else:
            print("Duplicate value: ", value)

    def delete(self, value):
        self.root = self._delete_recursive(self.root, value)

    def _delete_recursive(self, current_node, value):
        if not current_node:
            return current_node
        if value < current_node.value:
            current_node.left = self._delete_recursive(current_node.left, value)
        elif value > current_node.value:
            current_node.right = self._delete_recursive(current_node.right, value)
        else:
            if not current_node.left:
                return current_node.right
            elif not current_node.right:
                return current_node.left
            temp = self._min_value_node(current_node.right)
            current_node.value = temp.value
            current_node.right = self._delete_recursive(current_node.right, temp.value)
        return current_node

    def _min_value_node(self, node):
        current = node
        while current.left:
            current = current.left
        return current

    def search(self, value):
        return self._search_recursive(self.root, value)

    def _search_recursive(self, current_node, value):
        if not current_node or current_node.value == value:
            return current_node
        if value < current_node.value:
            return self._search_recursive(current_node.left, value)
        else:
            return self._search_recursive(current_node.right, value)

# Example usage:
bst = BinarySearchTree()
bst.insert(50)
bst.insert(30)
bst.insert(70)
bst.insert(20)
bst.insert(40)
bst.insert(60)
print(bst.search(40).value)  # Output: 40
bst.delete(30)
print(bst.search(30))  # Output: None
```

This Python code defines two classes: `TreeNode` and `BinarySearchTree`. The `TreeNode` class represents a node in the binary search tree, containing a value and pointers to its left and right children. The `BinarySearchTree` class manages the tree operations including insertion, deletion, and searching.

The `insert` method inserts a new node into the tree. It recursively searches for the correct position based on the value to be inserted.

The `delete` method removes a node from the tree. It uses a recursive approach to find the node to delete and then adjusts the tree structure accordingly.

The `search` method checks if a given value exists in the tree and returns the corresponding node if found.

The example usage demonstrates how to create a binary search tree, perform some operations (insertion, deletion, and search), and verify the correctness of these operations.

